SELECT s.*
FROM review_stats_daily s
INNER JOIN review_project p ON p.project_id = s.project_id
INNER JOIN sys_business_system bs ON bs.system_id = p.business_system_id
INNER JOIN sys_dept d ON d.dept_id = p.dept_id
INNER JOIN sys_user owner ON owner.user_id = p.owner_user_id
WHERE s.stat_date >= #{params.beginDate}
  AND s.stat_date <= #{params.endDate}

    AND s.project_id = #{projectId}


    AND p.business_system_id = #{params.businessSystemId}


    AND s.project_id IN

        #{pid}


${params.dataScope}

ORDER BY s.stat_date ASC, s.project_id ASC

